def fibonacci(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def lucas(n):
    if n == 0:
        return 2
    if n == 1:
        return 1
    a, b = 2, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# 1. Generate Fibonacci numbers up to F_125
F_set = set()
for k in range(2, 126):
    F_k = fibonacci(k)
    F_set.add(F_k)

# 2. Calculate L_100
L_100 = lucas(100)

# 3. Check if L_100 is in the required set of differences {F_2, ..., F_125}
is_equal = L_100 in F_set

print(f"L_100 calculated: {L_100}")
print(f"Is L_100 equal to any F_k for 2 <= k <= 125? {is_equal}")
print(f"Total number of unique required differences (F_2 to F_125): 124")
